/*LGVATT00016.retrieveAnnualLeave*/ SELECT ann.employee_no AS employee_no ,em.full_name_local AS employee_name ,em.org_name_local AS emp_org_name ,to_char(em.date_retire, 'DD/MM/YYYY') AS resignation_date ,ann.emp_type AS emp_type ,NVL(ann.annual_leave_days, GREATEST(0, LEAST(4, CEIL((MONTHS_BETWEEN( CASE WHEN em.date_retire IS NOT NULL THEN LEAST(em.date_retire, ann.effective_end_date) ELSE ann.effective_end_date END ,ann.effective_start_date) / 12 * (CASE WHEN ann.emp_type = '4' THEN 2 ELSE 4 END)) * 2) / 2))) AS annual_leave_days ,CASE WHEN ann.annual_leave_days IS NOT NULL THEN 'Y' ELSE 'N' END AS is_calculated ,to_char(ann.effective_start_date, 'DD/MM/YYYY') AS effective_start_date ,to_char(ann.effective_end_date, 'DD/MM/YYYY') AS effective_end_date ,to_char(ann.creation_date, 'DD/MM/YYYY') AS creation_date FROM tb_att_emp_annual_m ann ,emp_master em WHERE em.employee_number = ann.employee_no
AND em.employee_number = #{employeeNo}
AND em.full_name_local = #{employeeName}
AND em.organization_id = #{orgName}
AND to_char(ann.effective_end_date, 'YYYY') = #{timeAndAttendanceYyyy}
ORDER BY ann.employee_no

mapper.insert:
/*LGVATT00016.excelDownData*/ INSERT INTO xxlge_export_info (SESSION_ID, CREATED_BY, CREATION_DATE, SEQ_NO, CHARACTER_SET_NAME , ATTRIBUTE1, ATTRIBUTE2, ATTRIBUTE3, ATTRIBUTE4, ATTRIBUTE5, ATTRIBUTE6, ATTRIBUTE7, ATTRIBUTE8) SELECT AI.* FROM (SELECT #{sessionId} ,#{USER_SESSION.applicationUserId} ,SYSDATE ,1 ,'KO16KSC5601' ,'Employee No' AS employee_no ,'Employee Name' AS employee_name ,'Organization' AS emp_org_name ,'Resignation Date' AS resignation_date ,'Emp Type' AS emp_type ,'Annual Leave Days' AS annual_leave_days ,'Effective Start Date' AS effective_start_date ,'Effective End Date' AS effective_end_date FROM DUAL UNION ALL SELECT #{sessionId} ,#{USER_SESSION.applicationUserId} ,sysdate ,2 ,'KO16KSC5601' ,ann.employee_no AS employee_no ,em.full_name_local AS employee_name ,em.org_name_local AS emp_org_name ,to_char(em.date_retire, 'DD/MM/YYYY') AS resignation_date ,ann.emp_type AS emp_type ,to_char(NVL(ann.annual_leave_days, GREATEST(0, LEAST(4, CEIL((MONTHS_BETWEEN( CASE WHEN em.date_retire IS NOT NULL THEN LEAST(em.date_retire, ann.effective_end_date) ELSE ann.effective_end_date END ,ann.effective_start_date) / 12 * (CASE WHEN ann.emp_type = '4' THEN 2 ELSE 4 END)) * 2) / 2)))) AS annual_leave_days ,to_char(ann.effective_start_date, 'DD/MM/YYYY') AS effective_start_date ,to_char(ann.effective_end_date, 'DD/MM/YYYY') AS effective_end_date FROM tb_att_emp_annual_m ann ,emp_master em WHERE em.employee_number = ann.employee_no
AND em.employee_number = #{employeeNo}
AND em.full_name_local = #{employeeName}
AND em.organization_id = #{orgName}
AND to_char(ann.effective_end_date, 'YYYY') = #{timeAndAttendanceYyyy}
ORDER BY employee_no ) AI

mapper.update:
/*LGVATT00016.creditResidualAnnualLeaveDays*/
UPDATE tb_att_annual_leave_n aln
SET residual_annual_leave_days = NVL(residual_annual_leave_days, 0) + NVL((
		SELECT SUM(ann.annual_leave_days)
		FROM   tb_att_emp_annual_m ann
		WHERE  ann.employee_no = #{employeeNo}
		AND    
		       CASE WHEN TO_CHAR(ann.effective_start_date, 'YYYYMM') < TO_CHAR(ann.effective_end_date, 'YYYY') || '01'
		            THEN TO_CHAR(ann.effective_end_date, 'YYYY') || '01'
		            ELSE TO_CHAR(ann.effective_start_date, 'YYYYMM')
		       END  = #{targetYyyymm}
	), 0)
,last_update_user_id = #{applicationUserId}
,last_update_date = SYSDATE
WHERE aln.employee_no = #{employeeNo}
AND   aln.time_and_attendance_yyyymm = #{targetYyyymm}

/*LGVATT00016.creditAnnualCalibrationDays*/
UPDATE tb_att_annual_leave_n aln
SET annual_calibration_days = NVL(annual_calibration_days, 0) + NVL((
		SELECT SUM(ann.annual_leave_days)
		FROM   tb_att_emp_annual_m ann
		WHERE  ann.employee_no = #{employeeNo}
		AND    
		       CASE WHEN TO_CHAR(ann.effective_start_date, 'YYYYMM') < TO_CHAR(ann.effective_end_date, 'YYYY') || '01'
		            THEN TO_CHAR(ann.effective_end_date, 'YYYY') || '01'
		            ELSE TO_CHAR(ann.effective_start_date, 'YYYYMM')
		       END  = #{targetYyyymm}
	), 0)
,last_update_user_id = #{applicationUserId}
,last_update_date = SYSDATE
WHERE aln.employee_no = #{employeeNo}
AND   aln.time_and_attendance_yyyymm = #{prevYyyymm}

/*LGVATT00016.deleteAnnualLeave*/
DELETE FROM tb_att_emp_annual_m
WHERE employee_no = #{employeeNo}
AND   effective_start_date = to_date(#{effectiveStartDate}, 'DD/MM/YYYY')
